output_text:
[
  {
    "id": "get_cart_before_shopping",
    "text": "Customers should obtain a shopping cart before doing the shopping trip, expressed by the possession-changing interaction rather than by a fixed cart-station coordinate.",
    "abstraction": {
      "state_properties": {},
      "events": {
        "acquireCart": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "START",
      "discharge": "acquireCart"
    }
  },
  {
    "id": "exit_with_cart",
    "text": "Customers should not leave the store without their cart, a role-based exit norm independent of where the exit is located.",
    "abstraction": {
      "state_properties": {},
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "EXIT",
          {
            "not": "hasCart"
          }
        ]
      }
    }
  },
  {
    "id": "no_cart_in_single_file_shelf_aisle",
    "text": "Customers must not take carts into single-file shelf aisles, identified geometrically by opposing shelves and very small horizontal clearance rather than by aisle coordinates.",
    "abstraction": {
      "state_properties": {
        "betweenOpposingShelves": {
          "and": [
            "shelfE",
            "shelfW"
          ]
        },
        "singleFileShelfAisle": {
          "and": [
            "betweenOpposingShelves",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "hasCart",
          "singleFileShelfAisle"
        ]
      }
    }
  },
  {
    "id": "no_cart_shelf_interaction_in_single_file_aisle",
    "text": "Shelf interactions inside a single-file shelf aisle should be performed without a cart, which generalizes to any rotated or relocated narrow aisle described by local geometry.",
    "abstraction": {
      "state_properties": {
        "betweenOpposingShelves": {
          "and": [
            "shelfE",
            "shelfW"
          ]
        },
        "singleFileShelfAisle": {
          "and": [
            "betweenOpposingShelves",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        }
      },
      "events": {}
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "INTERACT",
          "hasCart",
          "singleFileShelfAisle"
        ]
      }
    }
  },
  {
    "id": "park_cart_only_in_open_clear_area",
    "text": "If a customer leaves a cart behind, it should be parked in an open clear circulation area rather than beside shelves or inside a constricted aisle, using local clearance and shelf adjacency instead of fixed parking spots.",
    "abstraction": {
      "state_properties": {
        "openClearArea": {
          "and": [
            {
              "gt": [
                "freeWidthH",
                1
              ]
            },
            {
              "not": "adjShelf"
            }
          ]
        }
      },
      "events": {
        "parkCart": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        }
      }
    },
    "norm": {
      "type": "prohibition",
      "condition": {
        "and": [
          "parkCart",
          {
            "not": "openClearArea"
          }
        ]
      }
    }
  },
  {
    "id": "parking_is_for_entering_no_cart_aisle",
    "text": "Parking a cart should be followed by a cart-free entry into a single-file shelf aisle, capturing the purpose of temporary parking without naming the aisle mouth location.",
    "abstraction": {
      "state_properties": {
        "betweenOpposingShelves": {
          "and": [
            "shelfE",
            "shelfW"
          ]
        },
        "singleFileShelfAisle": {
          "and": [
            "betweenOpposingShelves",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        }
      },
      "events": {
        "parkCart": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        },
        "enterSingleFileWithoutCart": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "MOVE"
            ]
          },
          "post": "singleFileShelfAisle"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "parkCart",
      "discharge": "enterSingleFileWithoutCart"
    }
  },
  {
    "id": "recover_parked_cart",
    "text": "A customer who parks a cart should retrieve it before finishing the trip, a general unattended-cart norm tied to cart-possession transitions rather than to a particular recovery coordinate.",
    "abstraction": {
      "state_properties": {},
      "events": {
        "parkCart": {
          "pre": {
            "and": [
              "hasCart",
              "INTERACT"
            ]
          },
          "post": {
            "not": "hasCart"
          }
        },
        "recoverCart": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "parkCart",
      "discharge": "recoverCart"
    }
  },
  {
    "id": "recover_after_leaving_single_file_aisle",
    "text": "After coming back out of a single-file shelf aisle without a cart, the customer should recover the parked cart, generalizing to any aisle exit defined by the transition from constrained shelf geometry to open space.",
    "abstraction": {
      "state_properties": {
        "betweenOpposingShelves": {
          "and": [
            "shelfE",
            "shelfW"
          ]
        },
        "singleFileShelfAisle": {
          "and": [
            "betweenOpposingShelves",
            {
              "le": [
                "freeWidthH",
                1
              ]
            }
          ]
        },
        "openClearArea": {
          "and": [
            {
              "gt": [
                "freeWidthH",
                1
              ]
            },
            {
              "not": "adjShelf"
            }
          ]
        }
      },
      "events": {
        "exitSingleFileWithoutCart": {
          "pre": {
            "and": [
              "singleFileShelfAisle",
              {
                "not": "hasCart"
              },
              "MOVE"
            ]
          },
          "post": "openClearArea"
        },
        "recoverCart": {
          "pre": {
            "and": [
              {
                "not": "hasCart"
              },
              "INTERACT"
            ]
          },
          "post": "hasCart"
        }
      }
    },
    "norm": {
      "type": "obligation",
      "trigger": "exitSingleFileWithoutCart",
      "discharge": "recoverCart"
    }
  }
]
